[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Leap Studio — Your Reinvention and Experience Partner</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg-primary: #0A0A0A;
      --bg-secondary: #111111;
      --bg-card: #141414;
      --text-primary: #FFFFFF;
      --text-secondary: #A0A0A0;
      --text-muted: #666666;
      --accent-blue: #3B82F6;
      --accent-amber: #F59E0B;
      --border-subtle: #222222;
    }

    * {
      font-family: 'Inter', system-ui, sans-serif;
      box-sizing: border-box;
    }

    body {
      background-color: var(--bg-primary);
      color: var(--text-primary);
      margin: 0;
      overflow-x: hidden;
    }

    /* Custom scrollbar */
    ::-webkit-scrollbar {
      width: 8px;
      height: 8px;
    }
    ::-webkit-scrollbar-track {
      background: var(--bg-primary);
    }
    ::-webkit-scrollbar-thumb {
      background: var(--text-muted);
      border-radius: 4px;
    }
    ::-webkit-scrollbar-thumb:hover {
      background: var(--text-secondary);
    }

    /* Hero Carousel */
    .hero-carousel {
      position: relative;
      overflow: hidden;
    }
    .hero-carousel-track {
      display: flex;
      transition: transform 500ms ease-out;
    }
    .hero-slide {
      min-width: 100%;
      position: relative;
    }
    .hero-slide-image {
      position: absolute;
      inset: 0;
      background-size: cover;
      background-position: center;
      opacity: 0.3;
    }
    .hero-slide-content {
      position: relative;
      z-index: 10;
    }

    /* Team Carousel */
    .team-carousel-track {
      display: flex;
      gap: 1.5rem;
      transition: transform 400ms ease-out;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
    }
    .team-carousel-track::-webkit-scrollbar {
      display: none;
    }
    .team-card {
      min-width: 320px;
      scroll-snap-align: start;
      flex-shrink: 0;
    }

    /* Work Carousel */
    .work-carousel-track {
      display: flex;
      gap: 1.5rem;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      padding-bottom: 1rem;
    }
    .work-carousel-track::-webkit-scrollbar {
      display: none;
    }
    .work-card {
      min-width: 380px;
      scroll-snap-align: start;
      flex-shrink: 0;
    }

    /* Navigation */
    .nav-link {
      position: relative;
      transition: color 200ms ease;
    }
    .nav-link::after {
      content: '';
      position: absolute;
      bottom: -2px;
      left: 0;
      width: 0;
      height: 1px;
      background: var(--text-primary);
      transition: width 200ms ease;
    }
    .nav-link:hover::after {
      width: 100%;
    }

    /* Language Dropdown */
    .language-dropdown {
      opacity: 0;
      visibility: hidden;
      transform: translateY(-8px);
      transition: all 200ms ease;
    }
    .language-dropdown.active {
      opacity: 1;
      visibility: visible;
      transform: translateY(0);
    }

    /* Cookie Banner */
    .cookie-banner {
      transform: translateY(100%);
      transition: transform 400ms ease-out;
    }
    .cookie-banner.active {
      transform: translateY(0);
    }

    /* Buttons */
    .btn-primary {
      background: var(--text-primary);
      color: var(--bg-primary);
      transition: all 150ms ease;
    }
    .btn-primary:hover {
      transform: scale(0.98);
    }
    .btn-secondary {
      border: 1px solid var(--border-subtle);
      transition: all 150ms ease;
    }
    .btn-secondary:hover {
      border-color: var(--text-secondary);
      background: rgba(255,255,255,0.05);
    }

    /* Region Tabs */
    .region-tab {
      transition: all 200ms ease;
      border-bottom: 2px solid transparent;
    }
    .region-tab.active {
      border-bottom-color: var(--text-primary);
    }

    /* Cards */
    .card-hover {
      transition: transform 200ms ease, box-shadow 200ms ease;
    }
    .card-hover:hover {
      transform: translateY(-4px);
      box-shadow: 0 20px 40px rgba(0,0,0,0.4);
    }

    /* Insights Grid */
    .insights-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 1.5rem;
    }
    @media (min-width: 1024px) {
      .insights-grid {
        grid-template-columns: repeat(4, 1fr);
      }
    }

    /* Mobile Menu */
    .mobile-menu {
      transform: translateX(100%);
      transition: transform 300ms ease;
    }
    .mobile-menu.active {
      transform: translateX(0);
    }

    /* Focus states for accessibility */
    button:focus-visible, a:focus-visible {
      outline: 2px solid var(--accent-blue);
      outline-offset: 2px;
    }

    /* Principle cards */
    .principle-card {
      border-left: 2px solid var(--text-muted);
      padding-left: 1.5rem;
    }

    /* Carousel indicators */
    .carousel-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--text-muted);
      transition: all 300ms ease;
    }
    .carousel-dot.active {
      background: var(--text-primary);
      width: 24px;
      border-radius: 4px;
    }

    /* Animations */
    @keyframes fadeIn {
      from { opacity: 0; transform: translateY(20px); }
      to { opacity: 1; transform: translateY(0); }
    }
    .animate-fadeIn {
      animation: fadeIn 600ms ease-out forwards;
    }

    /* Horizontal scroll hint on mobile */
    .scroll-hint {
      display: none;
    }
    @media (max-width: 768px) {
      .scroll-hint {
        display: flex;
        align-items: center;
        gap: 0.5rem;
        color: var(--text-secondary);
        font-size: 0.875rem;
      }
    }
  </style>
</head>
<body>
  <!-- Cookie Consent Banner -->
  <div id="cookieBanner" class="cookie-banner fixed bottom-0 left-0 right-0 z-50 bg-[#1a1a1a] border-t border-[#222] p-4 md:p-6">
    <div class="max-w-7xl mx-auto flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
      <p class="text-sm text-[#a0a0a0]">We use cookies to enhance your experience. By continuing, you agree to our <a href="#" class="underline hover:text-white">Cookie Policy</a>.</p>
      <div class="flex gap-3">
        <button onclick="acceptAllCookies()" class="btn-primary px-4 py-2 text-sm font-medium rounded-md">Accept All</button>
        <button onclick="manageCookieSettings()" class="btn-secondary px-4 py-2 text-sm font-medium rounded-md text-white">Manage Settings</button>
        <button onclick="declineAllCookies()" class="btn-secondary px-4 py-2 text-sm font-medium rounded-md text-white">Decline All</button>
      </div>
    </div>
  </div>

  <!-- Cookie Settings Modal -->
  <div id="cookieModal" class="fixed inset-0 z-50 hidden">
    <div class="absolute inset-0 bg-black/80" onclick="closeCookieModal()"></div>
    <div class="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-[#141414] border border-[#222] rounded-lg p-6 w-full max-w-md mx-4">
      <h3 class="text-lg font-semibold mb-4">Cookie Settings</h3>
      <div class="space-y-4">
        <div class="flex items-center justify-between">
          <span class="text-sm">Essential Cookies</span>
          <input type="checkbox" checked disabled class="w-5 h-5 accent-white">
        </div>
        <div class="flex items-center justify-between">
          <span class="text-sm">Analytics Cookies</span>
          <input type="checkbox" class="w-5 h-5 accent-white">
        </div>
        <div class="flex items-center justify-between">
          <span class="text-sm">Marketing Cookies</span>
          <input type="checkbox" class="w-5 h-5 accent-white">
        </div>
      </div>
      <button onclick="saveCookieSettings()" class="btn-primary w-full mt-6 py-2 rounded-md font-medium">Save Settings</button>
    </div>
  </div>

  <!-- Header -->
  <header class="fixed top-0 left-0 right-0 z-40 bg-[#0A0A0A]/90 backdrop-blur-md border-b border-[#111]">
    <nav class="max-w-7xl mx-auto px-4 md:px-6 h-16 flex items-center justify-between">
      <!-- Logo -->
      <a href="#" class="text-xl font-bold tracking-tight">LEAP STUDIO</a>

      <!-- Desktop Navigation -->
      <div class="hidden lg:flex items-center gap-8">
        <a href="#insights" class="nav-link text-sm text-[#a0a0a0] hover:text-white">Insights</a>
        <a href="#work" class="nav-link text-sm text-[#a0a0a0] hover:text-white">Work</a>
        <a href="#services" class="nav-link text-sm text-[#a0a0a0] hover:text-white">Services</a>
        <a href="#culture" class="nav-link text-sm text-[#a0a0a0] hover:text-white">Culture</a>
        <a href="#careers" class="nav-link text-sm text-[#a0a0a0] hover:text-white">Make Your Mark</a>
        <a href="#contact" class="nav-link text-sm text-[#a0a0a0] hover:text-white">Contact Us</a>
      </div>

      <!-- Right Side -->
      <div class="flex items-center gap-4">
        <!-- Language Selector -->
        <div class="relative">
          <button onclick="toggleLanguageDropdown()" class="flex items-center gap-2 text-sm text-[#a0a0a0] hover:text-white">
            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M2 12h20M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>
            <span>Global EN</span>
            <svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 9l6 6 6-6"/></svg>
          </button>
          <div id="languageDropdown" class="language-dropdown absolute top-full right-0 mt-2 bg-[#141414] border border-[#222] rounded-lg py-2 min-w-[140px]">
            <button class="w-full px-4 py-2 text-left text-sm hover:bg-[#222] text-white">Global EN</button>
            <button class="w-full px-4 py-2 text-left text-sm hover:bg-[#222] text-[#a0a0a0]">France FR</button>
            <button class="w-full px-4 py-2 text-left text-sm hover:bg-[#222] text-[#a0a0a0]">China CN</button>
          </div>
        </div>

        <!-- Mobile Menu Button -->
        <button onclick="toggleMobileMenu()" class="lg:hidden p-2 text-white">
          <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M4 6h16M4 12h16M4 18h16"/></svg>
        </button>
      </div>
    </nav>
  </header>

  <!-- Mobile Menu -->
  <div id="mobileMenu" class="mobile-menu fixed inset-0 z-50 bg-[#0A0A0A] lg:hidden">
    <div class="p-6">
      <div class="flex justify-between items-center mb-8">
        <span class="text-xl font-bold">LEAP STUDIO</span>
        <button onclick="toggleMobileMenu()" class="p-2 text-white">
          <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12"/></svg>
        </button>
      </div>
      <div class="flex flex-col gap-6">
        <a href="#insights" onclick="toggleMobileMenu()" class="text-2xl font-medium hover:text-[#a0a0a0]">Insights</a>
        <a href="#work" onclick="toggleMobileMenu()" class="text-2xl font-medium hover:text-[#a0a0a0]">Work</a>
        <a href="#services" onclick="toggleMobileMenu()" class="text-2xl font-medium hover:text-[#a0a0a0]">Services</a>
        <a href="#culture" onclick="toggleMobileMenu()" class="text-2xl font-medium hover:text-[#a0a0a0]">Culture</a>
        <a href="#careers" onclick="toggleMobileMenu()" class="text-2xl font-medium hover:text-[#a0a0a0]">Make Your Mark</a>
        <a href="#contact" onclick="toggleMobileMenu()" class="text-2xl font-medium hover:text-[#a0a0a0]">Contact Us</a>
      </div>
    </div>
  </div>

  <main>
    <!-- Hero Section -->
    <section class="hero-carousel min-h-screen flex items-center pt-16 relative overflow-hidden">
      <div class="hero-carousel-track" id="heroCarouselTrack">
        <!-- Slide 1: Futurescape -->
        <div class="hero-slide min-w-full py-20 md:py-32">
          <div class="hero-slide-image" style="background-image: url('https://images.unsplash.com/photo-1633356122544-f134518a8d4f?w=1920&h=1080&fit=crop')"></div>
          <div class="hero-slide-content max-w-7xl mx-auto px-4 md:px-6">
            <div class="max-w-2xl">
              <span class="inline-block px-3 py-1 bg-[#3B82F6]/20 text-[#3B82F6] text-xs font-medium rounded-full mb-4">Featured Report</span>
              <h1 class="text-4xl md:text-6xl lg:text-7xl font-bold leading-tight mb-6">Welcome to the Futurescape</h1>
              <p class="text-lg md:text-xl text-[#a0a0a0] mb-8">Discover trends and insights on the future of human-AI chemistry.</p>
              <a href="#" class="btn-primary inline-flex px-6 py-3 rounded-md font-medium">Read the report</a>
            </div>
          </div>
        </div>

        <!-- Slide 2: Designing Robots -->
        <div class="hero-slide min-w-full py-20 md:py-32">
          <div class="hero-slide-image" style="background-image: url('https://images.unsplash.com/photo-1485827404703-89b55fcc595e?w=1920&h=1080&fit=crop')"></div>
          <div class="hero-slide-content max-w-7xl mx-auto px-4 md:px-6">
            <div class="max-w-2xl">
              <span class="inline-block px-3 py-1 bg-[#F59E0B]/20 text-[#F59E0B] text-xs font-medium rounded-full mb-4">Project Highlight</span>
              <h1 class="text-4xl md:text-6xl lg:text-7xl font-bold leading-tight mb-6">Designing Robots for Human Spaces</h1>
              <p class="text-lg md:text-xl text-[#a0a0a0] mb-8">Meet 'Aura,' a concept from Leap Studio that offers a human-centered approach to physical AI.</p>
              <a href="#" class="btn-primary inline-flex px-6 py-3 rounded-md font-medium">Explore the work</a>
            </div>
          </div>
        </div>

        <!-- Slide 3: Amplifying Clinical Care -->
        <div class="hero-slide min-w-full py-20 md:py-32">
          <div class="hero-slide-image" style="background-image: url('https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=1920&h=1080&fit=crop')"></div>
          <div class="hero-slide-content max-w-7xl mx-auto px-4 md:px-6">
            <div class="max-w-2xl">
              <span class="inline-block px-3 py-1 bg-[#3B82F6]/20 text-[#3B82F6] text-xs font-medium rounded-full mb-4">Insight</span>
              <h1 class="text-4xl md:text-6xl lg:text-7xl font-bold leading-tight mb-6">Amplifying Clinical Care with AI</h1>
              <p class="text-lg md:text-xl text-[#a0a0a0] mb-8">Examining how service design helps experts understand the healthcare ecosystem.</p>
              <a href="#" class="btn-primary inline-flex px-6 py-3 rounded-md font-medium">Explore now</a>
            </div>
          </div>
        </div>

        <!-- Slide 4: Design Mind Leapcast -->
        <div class="hero-slide min-w-full py-20 md:py-32">
          <div class="hero-slide-image" style="background-image: url('https://images.unsplash.com/photo-1478737270239-2f02b77fc618?w=1920&h=1080&fit=crop')"></div>
          <div class="hero-slide-content max-w-7xl mx-auto px-4 md:px-6">
            <div class="max-w-2xl">
              <span class="inline-block px-3 py-1 bg-[#F59E0B]/20 text-[#F59E0B] text-xs font-medium rounded-full mb-4">Podcast</span>
              <h1 class="text-4xl md:text-6xl lg:text-7xl font-bold leading-tight mb-6">Design Mind Leapcast Ep. 55</h1>
              <p class="text-lg md:text-xl text-[#a0a0a0] mb-8">Peter Hallström, Global Head of Design at Lumina Health, discusses the evolution of product design and the role of design leadership.</p>
              <a href="#" class="btn-primary inline-flex px-6 py-3 rounded-md font-medium">Listen now</a>
            </div>
          </div>
        </div>

        <!-- Slide 5: From Complexity to Clarity -->
        <div class="hero-slide min-w-full py-20 md:py-32">
          <div class="hero-slide-image" style="background-image: url('https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=1920&h=1080&fit=crop')"></div>
          <div class="hero-slide-content max-w-7xl mx-auto px-4 md:px-6">
            <div class="max-w-2xl">
              <span class="inline-block px-3 py-1 bg-[#3B82F6]/20 text-[#3B82F6] text-xs font-medium rounded-full mb-4">Research</span>
              <h1 class="text-4xl md:text-6xl lg:text-7xl font-bold leading-tight mb-6">From Complexity to Clarity</h1>
              <p class="text-lg md:text-xl text-[#a0a0a0] mb-8">Dive into new research on how CMOs can reclaim marketing to build competitive edge.</p>
              <a href="#" class="btn-primary inline-flex px-6 py-3 rounded-md font-medium">Read the report</a>
            </div>
          </div>
        </div>
      </div>

      <!-- Hero Carousel Controls -->
      <div class="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-3">
        <button onclick="goToHeroSlide(0)" class="carousel-dot active" aria-label="Go to slide 1"></button>
        <button onclick="goToHeroSlide(1)" class="carousel-dot" aria-label="Go to slide 2"></button>
        <button onclick="goToHeroSlide(2)" class="carousel-dot" aria-label="Go to slide 3"></button>
        <button onclick="goToHeroSlide(3)" class="carousel-dot" aria-label="Go to slide 4"></button>
        <button onclick="goToHeroSlide(4)" class="carousel-dot" aria-label="Go to slide 5"></button>
      </div>

      <!-- Hero Navigation Arrows -->
      <button onclick="prevHeroSlide()" class="absolute left-4 top-1/2 -translate-y-1/2 p-2 bg-white/10 rounded-full hover:bg-white/20 hidden md:block" aria-label="Previous slide">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15 19l-7-7 7-7"/></svg>
      </button>
      <button onclick="nextHeroSlide()" class="absolute right-4 top-1/2 -translate-y-1/2 p-2 bg-white/10 rounded-full hover:bg-white/20 hidden md:block" aria-label="Next slide">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 5l7 7-7 7"/></svg>
      </button>
    </section>

    <!-- Team Carousel Section -->
    <section id="team" class="py-20 md:py-32 bg-[#111]">
      <div class="max-w-7xl mx-auto px-4 md:px-6">
        <div class="text-center mb-12">
          <h2 class="text-3xl md:text-5xl font-bold mb-4">Welcome to the studio</h2>
          <p class="text-[#a0a0a0] text-lg max-w-2xl mx-auto">Meet the team making an impact for leading brands around the globe.</p>
        </div>

        <!-- Region Tabs -->
        <div class="flex justify-center gap-4 md:gap-8 mb-12 flex-wrap">
