          <button onclick="setTeamRegion('europe')" class="region-tab text-sm md:text-base font-medium pb-2 text-[#666]" data-region="europe">Europe</button>
          <button onclick="setTeamRegion('oceania')" class="region-tab text-sm md:text-base font-medium pb-2 text-[#666]" data-region="oceania">Oceania</button>
        </div>

        <!-- Team Cards -->
        <div class="team-carousel-track" id="teamCarouselTrack">
          <!-- North America -->
          <div class="team-card bg-[#141414] rounded-lg p-6 card-hover" data-region="north-america">
            <div class="w-full h-48 bg-[#1a1a1a] rounded-lg mb-4 overflow-hidden">
              <img src="https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=400&h=300&fit=crop" alt="Denice Alvarez" class="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-300">
            </div>
            <p class="text-sm text-[#666] mb-2 italic">"As the Office Manager, I engage with teams from every discipline, and have learned so much through my day-to-day interactions with my fellow leapers."</p>
            <h3 class="font-semibold mb-1">Denice Alvarez</h3>
            <p class="text-sm text-[#a0a0a0] mb-3">Office Manager · New York</p>
            <a href="#" class="text-sm text-[#3B82F6] hover:underline">Contact Leap Studio New York →</a>
          </div>

          <div class="team-card bg-[#141414] rounded-lg p-6 card-hover" data-region="north-america">
            <div class="w-full h-48 bg-[#1a1a1a] rounded-lg mb-4 overflow-hidden">
              <img src="https://images.unsplash.com/photo-1560250097-0b93528c311a?w=400&h=300&fit=crop" alt="Marco Bellini" class="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-300">
            </div>
            <p class="text-sm text-[#666] mb-2 italic">"Every day we are delighted by the immense beauty that nature holds. When engaged in the act of creation, it is our responsibility to channel that delight into the things we make."</p>
            <h3 class="font-semibold mb-1">Marco Bellini</h3>
            <p class="text-sm text-[#a0a0a0] mb-3">Design Director · San Francisco</p>
            <a href="#" class="text-sm text-[#3B82F6] hover:underline">Contact Leap Studio San Francisco →</a>
          </div>

          <!-- Asia -->
          <div class="team-card bg-[#141414] rounded-lg p-6 card-hover" data-region="asia">
            <div class="w-full h-48 bg-[#1a1a1a] rounded-lg mb-4 overflow-hidden">
              <img src="https://images.unsplash.com/photo-1594824472247-229505d8d670?w=400&h=300&fit=crop" alt="Priya Mehta" class="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-300">
            </div>
            <p class="text-sm text-[#666] mb-2 italic">"We bring your brand vision to life, with transformative ideas and impactful marketing campaigns fueled by creativity and enthusiasm."</p>
            <h3 class="font-semibold mb-1">Priya Mehta</h3>
            <p class="text-sm text-[#a0a0a0] mb-3">Studio Head · Bangalore</p>
            <a href="#" class="text-sm text-[#3B82F6] hover:underline">Contact Leap Studio Bangalore →</a>
          </div>

