  <script>
    // Hero Carousel State
    let currentHeroSlide = 0;
    const heroSlideCount = 5;

    function updateHeroCarousel() {
      const track = document.getElementById('heroCarouselTrack');
      track.style.transform = `translateX(-${currentHeroSlide * 100}%)`;

      // Update dots
      document.querySelectorAll('.carousel-dot').forEach((dot, index) => {
        dot.classList.toggle('active', index === currentHeroSlide);
      });
    }

    function nextHeroSlide() {
      currentHeroSlide = (currentHeroSlide + 1) % heroSlideCount;
      updateHeroCarousel();
    }

    function prevHeroSlide() {
      currentHeroSlide = (currentHeroSlide - 1 + heroSlideCount) % heroSlideCount;
      updateHeroCarousel();
    }

    function goToHeroSlide(index) {
      currentHeroSlide = index;
      updateHeroCarousel();
    }

    // Auto-advance hero carousel every 6 seconds
    setInterval(nextHeroSlide, 6000);

    // Team Region Toggle
    let currentTeamRegion = 'north-america';

    function setTeamRegion(region) {
      currentTeamRegion = region;

      // Update tab states
      document.querySelectorAll('.region-tab').forEach(tab => {
        tab.classList.toggle('active', tab.dataset.region === region);
        tab.classList.toggle('text-[#666]', tab.dataset.region !== region);
      });

      // Filter team cards
      const track = document.getElementById('teamCarouselTrack');
      const cards = track.querySelectorAll('.team-card');
      let firstVisibleCard = null;

      cards.forEach(card => {
        const isVisible = card.dataset.region === region;
        card.style.display = isVisible ? 'block' : 'none';
        if (isVisible && !firstVisibleCard) {
          firstVisibleCard = card;
        }
      });

      // Reset scroll position
      track.scrollLeft = 0;
    }

    // Language Dropdown Toggle
    function toggleLanguageDropdown() {
      const dropdown = document.getElementById('languageDropdown');
      dropdown.classList.toggle('active');
    }

    // Close language dropdown when clicking outside
    document.addEventListener('click', (e) => {
      const dropdown = document.getElementById('languageDropdown');
      const button = e.target.closest('button');
      if (!button && dropdown.classList.contains('active')) {
        dropdown.classList.remove('active');
      }
    });

    // Mobile Menu Toggle
    function toggleMobileMenu() {
      const menu = document.getElementById('mobileMenu');
      menu.classList.toggle('active');
      document.body.style.overflow = menu.classList.contains('active') ? 'hidden' : '';
    }

    // Cookie Banner Functions
    function acceptAllCookies() {
      document.getElementById('cookieBanner').classList.remove('active');
      localStorage.setItem('cookieConsent', 'all');
    }

    function declineAllCookies() {
      document.getElementById('cookieBanner').classList.remove('active');
      localStorage.setItem('cookieConsent', 'declined');
    }

    function manageCookieSettings() {
      document.getElementById('cookieModal').classList.remove('hidden');
    }

    function closeCookieModal() {
      document.getElementById('cookieModal').classList.add('hidden');
    }

    function saveCookieSettings() {
      document.getElementById('cookieModal').classList.add('hidden');
      localStorage.setItem('cookieConsent', 'custom');
    }

    function openCookieSettings() {
      document.getElementById('cookieBanner').classList.add('active');
      setTimeout(() => {
        document.getElementById('cookieBanner').scrollIntoView({ behavior: 'smooth' });
      }, 100);
    }

    // Show cookie banner on first visit
    if (!localStorage.getItem('cookieConsent')) {
      setTimeout(() => {
        document.getElementById('cookieBanner').classList.add('active');
      }, 1500);
    }

    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
      anchor.addEventListener('click', function(e) {
        const href = this.getAttribute('href');
        if (href !== '#') {
          e.preventDefault();
          const target = document.querySelector(href);
          if (target) {
            target.scrollIntoView({ behavior: 'smooth', block: 'start' });
          }
        }
      });
    });

    // Initialize team carousel with North America selected
    setTeamRegion('north-america');
  </script>
</body>
</html>
